// VMOptions=--optimization-counter-threshold=10 --no-background-compilation

// Checks Int32x4 and Float32x4 shuffle and shuffleMix for all 256 masks.
//
// The VM only lowers a shuffle whose mask is a constant, so every mask gets
// its own function.

// The functions after `main` and the entries of `cases` are generated by:
//
// ```dart
// void main() {
//   final functions = StringBuffer();
//   final entries = StringBuffer();
//   for (var m = 0; m < 256; m++) {
//     final h = m.toRadixString(16).padLeft(2, '0');
//     final c = '0x${h.toUpperCase()}';
//     for (final (name, type, params, call) in [
//       ('is', 'Int32x4', 'Int32x4 a', 'shuffle($c)'),
//       ('fs', 'Float32x4', 'Float32x4 a', 'shuffle($c)'),
//       ('im', 'Int32x4', 'Int32x4 a, Int32x4 b', 'shuffleMix(b, $c)'),
//       ('fm', 'Float32x4', 'Float32x4 a, Float32x4 b', 'shuffleMix(b, $c)'),
//     ]) {
//       functions.writeln("@pragma('vm:never-inline')");
//       functions.writeln('$type $name$h($params) => a.$call;');
//     }
//     entries.writeln('  ($c, is$h, fs$h, im$h, fm$h),');
//   }
//   print(functions);
//   print(entries);
// }
// ```

import 'dart:typed_data';

import "package:expect/expect.dart";

void main() {
  final a = Int32x4(0x11111111, 0x22222222, 0x33333333, 0x44444444);
  final b = Int32x4(-0x55555556, -0x66666667, -0x77777778, 0x12345678);
  final fa = Float32x4(1.5, 2.5, -3.5, 4.5);
  final fb = Float32x4(-5.25, 6.25, 7.25, -8.25);

  void check(Case c) {
    List<int> lanes(Int32x4 v) => [v.x, v.y, v.z, v.w];
    List<double> flanes(Float32x4 v) => [v.x, v.y, v.z, v.w];

    List<T> shuffled<T>(List<T> x, int mask) => [
      for (var i = 0; i < 4; i++) x[(mask >> (2 * i)) & 3],
    ];

    List<T> mixed<T>(List<T> x, List<T> y, int mask) => [
      x[mask & 3],
      x[(mask >> 2) & 3],
      y[(mask >> 4) & 3],
      y[(mask >> 6) & 3],
    ];

    final (m, iS, fS, iM, fM) = c;
    final la = lanes(a);
    final lb = lanes(b);

    final fla = flanes(fa);
    final flb = flanes(fb);
    final reason = 'mask 0x${m.toRadixString(16)}';
    Expect.listEquals(shuffled(la, m), lanes(iS(a)), 'Int32x4.shuffle $reason');
    Expect.listEquals(
      shuffled(fla, m),
      flanes(fS(fa)),
      'Float32x4.shuffle $reason',
    );
    final mix = mixed(la, lb, m);
    Expect.listEquals(mix, lanes(iM(a, b)), 'Int32x4.shuffleMix $reason');
    Expect.listEquals(
      mixed(fla, flb, m),
      flanes(fM(fa, fb)),
      'Float32x4.shuffleMix $reason',
    );
  }

  for (var i = 0; i < 20; i++) {
    for (final c in cases) {
      check(c);
    }
  }
}

